processor-info.script:

	String cmd = input.getText("cmd");		
	String dynamic_sql = "";
	if("createJobBoard".equals(cmd))
	{
		String content = input.getText("cntnt");

		if("-1".equals(input.getText("brd_no")))
		{	
			if("-1".equals(input.getText("p_brd_no")))				
			{
				executeSQL("newBoard", connection, input, output);

				input.put("ins_brd_no", output.getText("ins_brd_no"));						
			} else
			{
				executeSQL("newAnswerBoard", connection, input, output);
			}					
		} 
		else
		{
			input.put("ins_brd_no", input.getText("brd_no"));
			executeSQL("updateBoard", connection, input, output);					
		}

		executeSQL("addJob", connection, input, output);		

		if (input.getCount("file_nm") > 0) {
            DataSet fileInfo = new DataSet();
            DataSet fileInfoOut = new DataSet();
            for (int i = 0, ic = input.getCount("file_nm"); i < ic; i++) {
                fileInfo.put("file_nm", input.getText("file_nm", i), i);
                fileInfo.put("file_path", input.getText("file_path", i), i);
                fileInfo.put("file_size", input.getText("file_size", i), i);
                fileInfo.put("ext_nm", input.getText("ext_nm", i), i);
                fileInfo.put("user_file_nm", input.getText("user_file_nm", i), i);
                fileInfo.put("attach_div_cd", input.getText("attach_div_cd"), i);
                fileInfo.put("data_no", input.getText("ins_brd_no"), i);
            }

            fileInfo.put("cmd", "create");
            executeTxBL("/common/Attach", fileInfo, fileInfoOut);
        }
	}
	else if("doBoardAdd".equals(cmd))
	{

		String content = input.getText("board_txt");

		if("-1".equals(input.getText("brd_no")))
		{	
			if("-1".equals(input.getText("p_brd_no")))				
			{
				executeSQL("newBoard", connection, input, output);

				input.put("ins_brd_no", output.getText("ins_brd_no"));						
			} else
			{
				executeSQL("newAnswerBoard", connection, input, output);
			}					
		} 
		else
		{
			input.put("ins_brd_no", input.getText("brd_no"));
			executeSQL("updateBoard", connection, input, output);					
		}



		if (input.getCount("file_nm") > 0) {
            DataSet fileInfo = new DataSet();
            DataSet fileInfoOut = new DataSet();
            for (int i = 0, ic = input.getCount("file_nm"); i < ic; i++) {
                fileInfo.put("file_nm", input.getText("file_nm", i), i);
                fileInfo.put("file_path", input.getText("file_path", i), i);
                fileInfo.put("file_size", input.getText("file_size", i), i);
                fileInfo.put("ext_nm", input.getText("ext_nm", i), i);
                fileInfo.put("user_file_nm", input.getText("user_file_nm", i), i);
                fileInfo.put("attach_div_cd", input.getText("attach_div_cd"), i);
                fileInfo.put("data_no", input.getText("ins_brd_no"), i);
            }

            fileInfo.put("cmd", "create");
            System.err.println(fileInfo);
            executeTxBL("/common/Attach", fileInfo, fileInfoOut);
        }


	}
	else if("doBoardRead".equals(cmd))
	{
		if(!input.getText("brd_no").equals("-1")){
			//if(!"".equals(input.getText("emp_no")))

			executeSQL("add_read_hst", connection, input, output);

			input.put("pre_brd_no", output.getText("pre_brd_no"));
			input.put("next_brd_no", output.getText("next_brd_no"));

			executeSQL(cmd, connection, input, output);
		}else{
			output.put("grp_seq_no", input.getText("grp_seq_no"));
			output.put("grp_order", input.getText("grp_order"));
			output.put("lvl", input.getText("lvl"));
		}
	} 	
	else if("doAuthCheck".equals(cmd))
	{
		executeSQL("doReadAuthCheck", connection, input, output);
		executeSQL("doanswerAuthCheck", connection, input, output);
	} else if("getBoard".equals(cmd))
	{
		String start_dt = input.getText("start_dt");
		String end_dt = input.getText("end_dt");
		if(!"".equals(start_dt) && !"".equals(end_dt) )
		{
			dynamic_sql = " AND a.reg_ddtm between CONVERT(DATETIME, '"+start_dt+"'+' 00:00:00') AND CONVERT(DATETIME, '"+end_dt+"'+' 23:59:59') ";

		} else
		{
			dynamic_sql = "";
		}
		input.put("dynamic_sql", dynamic_sql);

		String notice_yn = input.getText("notice_yn");
		String sqlNoticeYn = "";

		if("Y".equals(notice_yn))	sqlNoticeYn = " and notice_div is not null ";
		else if("N".equals(notice_yn))	sqlNoticeYn = " and notice_div is null ";

		input.put("sqlNoticeYn" ,sqlNoticeYn );

		executeSQL(cmd, connection, input, output);
	} else if("getNoticeList".equals(cmd))
	{
		String srch_type = input.getText("search_type");
		String srch_text = input.getText("search_txt");
		if("ttl".equals(srch_type))
		{
			dynamic_sql = " b.ttl like '%'+'"+srch_text+"'+'%'";

		} else
		{
			dynamic_sql = " 0 = 0";
		}
		input.put("dynamic_sql", dynamic_sql);
		executeSQL(cmd, connection, input, output);
	} else if("deleteJob".equals(cmd))
	{
		executeSQL("delJob", connection, input, output);
		executeSQL("delBoard", connection, input, output);
	}
	else if("delBoard".equals(cmd))
	{
		executeSQL("doCommentDelAll", connection, input, output);
		executeSQL("delBoard", connection, input, output);
	}	
	else
	{
		executeSQL(cmd, connection, input, output);
	}

sql.query:
SELECT TOP (?) num, a.brd_nm, a.brd_no, a.ttl, a.emp_nm, CONVERT(varchar(10), a.reg_dt,120) AS reg_dt, a.grp_seq_no, a.grp_order, a.lvl, a.p_brd_no, a.reg_emp_cd, (SELECT COUNT(*) FROM tb_kabm_board_read_hst WHERE brd_no = a.brd_no) AS read_count, tot_cnt, email, file_no, file_nm, file_path,brd_mng_no FROM (
SELECT c.brd_nm, a.brd_no, a.ttl, a.reg_emp_cd , b.emp_nm, b.email, a.reg_ddtm reg_dt, a.grp_seq_no, a.grp_order, a.lvl, a.p_brd_no, ROW_NUMBER() OVER(order by a.reg_ddtm desc) num, count(*) over() tot_cnt, d.file_no, d.file_nm, d.file_path,a.brd_mng_no FROM tb_kabm_board a LEFT JOIN tb_kabm_emp b ON a.reg_emp_cd = b.emp_cd LEFT JOIN tb_kabm_board_mngr c ON a.BRD_MNG_NO = c.BRD_MNG_NO LEFT JOIN tb_kabm_attach_file d ON a.brd_no = d.data_no AND d.attach_div_cd = 'attach_div_03' WHERE 1=1 AND a.grp_seq_no > 0 AND a.del_yn = 'N' AND a.grp_order > 0 AND a.brd_mng_no = ?
) a WHERE num > (? -1) * ? order by num
